@@ -0,0 +1,76 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { app } from "./helpers.js";
+
+const headers = { "X-Larder-Site": "annex" };
+
+function setup() {
+  const result = app();
+  result.store.data.batches.push({ id: 10, itemId: 2, qty: 3, location: "annex-fridge", lot: "ANNEX", receivedOn: "2026-10-28", expires: "2026-10-29" });
+  result.store.data.seq.batch = 10;
+  return result;
+}
+
+test("site headers default to main, ignore case and reject unknown sites", async () => {
+  const { handle } = setup();
+  assert.equal((await handle({ path: "/items/2" })).body.onHand, 10);
+  assert.equal((await handle({ path: "/items/2", headers })).body.onHand, 3);
+  assert.equal((await handle({ path: "/items/2", headers: { "x-larder-site": "annex" } })).body.onHand, 3);
+  const bad = await handle({ path: "/items", headers: { "X-Larder-Site": "missing" } });
+  assert.equal(bad.status, 400);
+  assert.equal(bad.body.error.code, "unknown_site");
+});
+
+test("batch reads, waste, alerts and value only use the selected site", async () => {
+  const { handle, store } = setup();
+  assert.deepEqual((await handle({ path: "/batches", headers })).body.map((b) => b.id), [10]);
+  assert.deepEqual((await handle({ path: "/batches?itemId=1", headers })).body, []);
+  assert.equal((await handle({ path: "/batches/1", headers })).status, 404);
+  assert.equal((await handle({ path: "/batches/10" })).status, 404);
+  const before = structuredClone(store.data);
+  assert.equal((await handle({ method: "POST", path: "/batches/1/waste", headers, body: { qty: 1 } })).status, 404);
+  assert.deepEqual(store.data, before);
+  const alerts = (await handle({ path: "/alerts", headers })).body;
+  assert.deepEqual(alerts.expiring.map((b) => b.id), [10]);
+  assert.equal(alerts.lowStock.find((i) => i.itemId === 2).qty, 3);
+  assert.equal((await handle({ path: "/reports/stock-value", headers })).body.totalCents, 387);
+});
+
+test("cooking cannot borrow stock from another kitchen and succeeds with local stock", async () => {
+  const { handle, store } = setup();
+  const before = structuredClone(store.data);
+  const request = { method: "POST", path: "/recipes/2/cook", headers, body: { portions: 10 } };
+  assert.equal((await handle(request)).status, 409);
+  assert.deepEqual(store.data, before);
+  for (const [id, itemId] of [[11, 3], [12, 4]])
+    store.data.batches.push({ ...store.data.batches.at(-1), id, itemId, qty: 1 });
+  const cooked = await handle(request);
+  assert.equal(cooked.status, 200);
+  assert.deepEqual(store.data.batches.slice(0, 9), before.batches.slice(0, 9));
+  assert.equal(store.data.batches.find((b) => b.id === 10).qty, 1);
+});
+
+test("stock-take locations, counts and finish cannot cross sites", async () => {
+  const { handle, store } = setup();
+  assert.equal((await handle({ method: "POST", path: "/stocktakes", body: { location: "annex-fridge" } })).status, 400);
+  const take = (await handle({ method: "POST", path: "/stocktakes", headers, body: { location: "annex-fridge" } })).body;
+  const before = structuredClone(store.data);
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, body: { batchId: 10, counted: 2 } })).status, 404);
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/finish` })).status, 404);
+  assert.deepEqual(store.data, before);
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, headers, body: { batchId: 1, counted: 2 } })).status, 404);
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, headers, body: { batchId: 10, counted: 2 } })).status, 200);
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/finish`, headers })).status, 200);
+  assert.equal(store.data.batches.find((b) => b.id === 10).qty, 2);
+});
+
+test("order receipts reject another site's locations before making changes", async () => {
+  const { handle, store } = setup();
+  const before = structuredClone(store.data);
+  const lots = [{ lot: "a", expires: null, location: "annex-fridge" }, { lot: "b", expires: null, location: "fridge" }];
+  assert.equal((await handle({ method: "POST", path: "/orders/2/receive", headers, body: { lots } })).status, 400);
+  assert.deepEqual(store.data, before);
+  lots[1].location = "annex-fridge";
+  assert.equal((await handle({ method: "POST", path: "/orders/2/receive", headers, body: { lots } })).status, 200);
+  assert.ok(store.data.batches.slice(-2).every((b) => b.location === "annex-fridge"));
+});
